import{_ as t,o as r,c as n,ah as s}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Internat","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/internat/index.md","filePath":"src/guide/internat/index.md"}'),a={name:"guide/internat/index.md"};function i(l,e,o,u,c,p){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="internat" tabindex="-1">Internat <a class="header-anchor" href="#internat" aria-label="Permalink to &quot;Internat&quot;">​</a></h1><p>En tant que responsable de l&#39;internat, vous avez deux missions dans ERA : gérer les lits (les créer, les modifier, et affecter un élève interne à chacun) et enregistrer chaque jour les présences en internat, le soir et le matin. Le menu de gauche vous donne accès à deux pages, sous la section « Internat » : <strong>Internat — Lits</strong> et <strong>Présences internat</strong>.</p><h2 id="gerer-les-lits" tabindex="-1">Gérer les lits <a class="header-anchor" href="#gerer-les-lits" aria-label="Permalink to &quot;Gérer les lits&quot;">​</a></h2><p>La page <strong>Internat — Lits</strong> liste tous les lits de l&#39;internat, avec le site, la chambre, le lit et l&#39;élève qui l&#39;occupe (ou « Non affecté » s&#39;il est libre). Vous pouvez filtrer la liste par site avec le menu déroulant en haut de la page, ou rechercher un lit par code de chambre ou de lit. Cliquez sur une ligne pour ouvrir un panneau récapitulatif avec le site et l&#39;occupant.</p><h3 id="creer-un-lit" tabindex="-1">Créer un lit <a class="header-anchor" href="#creer-un-lit" aria-label="Permalink to &quot;Créer un lit&quot;">​</a></h3><ol><li>Cliquez sur <strong>Nouveau lit</strong> en haut de la page <strong>Internat — Lits</strong>.</li><li>Choisissez le <strong>Site</strong> auquel appartient ce lit.</li><li>Renseignez la <strong>Chambre</strong> (le code de la chambre) et le <strong>Lit</strong> (le code du lit dans cette chambre).</li><li>Si un élève interne doit occuper ce lit dès sa création, sélectionnez-le dans le champ <strong>Occupant</strong>. Vous pouvez laisser ce champ vide et affecter un élève plus tard.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Seuls les élèves qui n&#39;ont pas encore de lit apparaissent dans la liste <strong>Occupant</strong> (en plus, sur la page de modification, de l&#39;élève déjà affecté à ce lit).</p><h3 id="modifier-un-lit-ou-reaffecter-son-occupant" tabindex="-1">Modifier un lit ou réaffecter son occupant <a class="header-anchor" href="#modifier-un-lit-ou-reaffecter-son-occupant" aria-label="Permalink to &quot;Modifier un lit ou réaffecter son occupant&quot;">​</a></h3><ol><li>Depuis la page <strong>Internat — Lits</strong>, cliquez sur <strong>Modifier</strong> sur la ligne du lit concerné.</li><li>Mettez à jour le site, la chambre, le lit ou l&#39;occupant selon les besoins. Pour libérer un lit, choisissez à nouveau <strong>Non affecté</strong> dans le champ <strong>Occupant</strong> ; pour affecter un autre élève, sélectionnez-le dans la liste.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol><h3 id="supprimer-un-lit" tabindex="-1">Supprimer un lit <a class="header-anchor" href="#supprimer-un-lit" aria-label="Permalink to &quot;Supprimer un lit&quot;">​</a></h3><p>Depuis la page <strong>Internat — Lits</strong>, cliquez sur <strong>Supprimer</strong> sur la ligne du lit concerné, puis confirmez dans la fenêtre qui s&#39;affiche. Un lit occupé ne peut pas être supprimé : libérez d&#39;abord son occupant (en modifiant le lit et en repassant l&#39;<strong>Occupant</strong> sur « Non affecté ») avant de le supprimer.</p><h2 id="enregistrer-les-presences-en-internat" tabindex="-1">Enregistrer les présences en internat <a class="header-anchor" href="#enregistrer-les-presences-en-internat" aria-label="Permalink to &quot;Enregistrer les présences en internat&quot;">​</a></h2><p>La page <strong>Présences internat</strong> vous permet de saisir, pour chaque élève ayant un lit affecté, s&#39;il est présent ou absent — le soir ou le matin. Seuls les élèves ayant déjà un lit affecté (voir « Gérer les lits » ci-dessus) apparaissent dans cette liste ; si la liste est vide, c&#39;est qu&#39;aucun lit n&#39;est encore affecté.</p><ol><li>Ouvrez la page <strong>Présences internat</strong>.</li><li>Choisissez la <strong>date</strong> concernée avec le sélecteur de date en haut de la page.</li><li>Choisissez le <strong>moment</strong> : <strong>Soir</strong> ou <strong>Matin</strong>. Changer la date ou le moment recharge automatiquement la liste avec les présences déjà saisies pour ce choix, s&#39;il y en a.</li><li>Pour chaque élève de la liste (avec son site, sa chambre et son lit), choisissez son statut dans le menu déroulant correspondant : <strong>Présent</strong> ou <strong>Absent</strong>.</li><li>Une fois toutes les lignes vérifiées, cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Vous pouvez revenir sur une date déjà saisie à tout moment pour corriger un statut : les valeurs déjà enregistrées pour cette date et ce moment sont pré-remplies.</p>',15)])])}const h=t(a,[["render",i]]);export{g as __pageData,h as default};
